-- Generated from the same validated rows as the CSV. Never runs automatically.
BEGIN;
SET LOCAL standard_conforming_strings = on;
SELECT pg_advisory_xact_lock(hashtext('mealsolved-recipe-import'));
CREATE TEMP TABLE incoming_recipes AS
SELECT title, description, meal_time, prep_time_mins, effort_score, servings, tags, image_url, ingredients_list, shopping_list, recipe_steps, cuisine, user_id, is_user_created, source_url, source_name FROM jsonb_populate_recordset(NULL::public.recipes, '[{"title":"Boxed Beef Pasta with Green Beans","description":"A familiar Hamburger Helper dinner with frozen green beans. Makes four meal portions; check your box''s liquid amounts before starting.","meal_time":["lunch","dinner"],"prep_time_mins":30,"effort_score":1,"servings":4,"tags":["easy","comfort-food","boxed-dinner","one-pan","family-dinner","quick"],"image_url":"","ingredients_list":["1 lb ground beef","1 box Hamburger Helper beef pasta, regular size","2 cups hot water","1 cup milk","1 1/2 cups frozen cut green beans"],"shopping_list":["1 lb ground beef","1 box Hamburger Helper beef pasta, regular size","1 cup milk","1 1/2 cups frozen cut green beans"],"recipe_steps":["In a deep skillet over medium-high heat, crumble and cook the beef for about 7 minutes, until it reaches 160°F. Spoon excess fat into a heatproof container.","Add the pasta and seasoning from the box, green beans, milk and water. If your box specifies different liquid amounts, use those. Bring to a boil.","Cover and simmer on low, stirring occasionally, until the pasta and beans are tender, about 10-12 minutes or the package time. Add a splash of water if needed. Rest off the heat for 5 minutes."],"cuisine":"American","user_id":null,"is_user_created":false,"source_url":"https://www.bettycrocker.com/recipes/green-bean-and-beef-pasta-supper/56a3af35-f2d7-4e97-a8e3-198cba211f1a","source_name":"Betty Crocker Kitchens"},{"title":"Boxed Mac and Canned Chili Dinner","description":"An easy chili mac using a whole box and a can. Make dinner and save a portion for another day.","meal_time":["lunch","dinner"],"prep_time_mins":25,"effort_score":1,"servings":3,"tags":["easy","comfort-food","boxed-dinner","beginner-friendly","quick"],"image_url":"","ingredients_list":["1 box original macaroni and cheese, 7.25 oz","4 tbsp butter","1/4 cup milk","1 can beef chili with beans, 15 oz"],"shopping_list":["1 box original macaroni and cheese, 7.25 oz","4 tbsp butter","1/4 cup milk","1 can beef chili with beans, 15 oz"],"recipe_steps":["Boil the macaroni in a saucepan following its box directions, usually 7-8 minutes after the water boils. Drain carefully.","Return the pasta to the pan. Mix in the cheese packet, butter and milk. The amounts listed suit a standard original box; follow your package if it differs.","Stir in the canned chili. Heat gently, stirring often, until hot throughout, about 3-5 minutes. Refrigerate spare portions promptly and reheat leftovers to 165°F."],"cuisine":"American","user_id":null,"is_user_created":false,"source_url":"https://www.reddit.com/r/EatCheapAndHealthy/comments/cu0slr/","source_name":"r/EatCheapAndHealthy community meal idea"},{"title":"Shortcut Biscuits and Sausage Gravy","description":"Breakfast for dinner with store-bought biscuits and simple skillet gravy. Use biscuits that bake in about 15 minutes.","meal_time":["breakfast","dinner"],"prep_time_mins":30,"effort_score":1,"servings":2,"tags":["easy","comfort-food","breakfast-for-dinner","small-batch","quick"],"image_url":"","ingredients_list":["4 refrigerated biscuit dough rounds","1/4 lb bulk pork breakfast sausage","3/4 tbsp butter","1 tbsp all-purpose flour","1 cup milk","1/8 tsp black pepper"],"shopping_list":["4 refrigerated biscuit dough rounds","1/4 lb bulk pork breakfast sausage","3/4 tbsp butter","1 tbsp all-purpose flour","1 cup milk","1/8 tsp black pepper"],"recipe_steps":["Preheat the oven and bake the biscuits on a tray according to their package directions.","While they bake, crumble the sausage into a skillet over medium heat. Cook until it reaches 160°F, about 6-8 minutes. Stir in butter and flour; cook while stirring for 2 minutes.","Gradually stir in milk, breaking up any flour lumps. Simmer gently, stirring, until thickened, about 5 minutes. Add pepper and spoon the gravy over the baked biscuits."],"cuisine":"American","user_id":null,"is_user_created":false,"source_url":"https://www.budgetbytes.com/country-sausage-gravy/","source_name":"Beth Moncel, Budget Bytes"},{"title":"Rotisserie Chicken and Stuffing Bake","description":"About 15 minutes of hands-on work and 60 minutes total. Cooked chicken, boxed stuffing and zucchini make a filling oven dinner.","meal_time":["lunch","dinner"],"prep_time_mins":60,"effort_score":2,"servings":4,"tags":["easy","comfort-food","oven-meal","low-active-time","family-dinner"],"image_url":"","ingredients_list":["1 box herb stuffing mix, 6 oz","4 tbsp butter, melted","4 cups cooked shredded rotisserie chicken","2 medium zucchini, diced small","1 can condensed cream of chicken soup, 10.5 oz","1/2 cup sour cream","1 tsp cooking oil"],"shopping_list":["1 box herb stuffing mix, 6 oz","4 tbsp butter, melted","4 cups cooked shredded rotisserie chicken","2 medium zucchini, diced small","1 can condensed cream of chicken soup, 10.5 oz","1/2 cup sour cream","1 tsp cooking oil"],"recipe_steps":["Heat the oven to 350°F. Lightly oil a 9-by-13-inch baking dish.","Toss the dry stuffing with melted butter. Set aside a small handful for the top. Mix the rest with chicken, zucchini, condensed soup and sour cream.","Spread in the dish and scatter the reserved stuffing over it. Bake for 40-45 minutes, until the zucchini is tender and the center reaches 165°F; allow longer if needed. Rest 5 minutes before serving."],"cuisine":"American","user_id":null,"is_user_created":false,"source_url":"https://www.juliapacheco.com/zucchini-stuffing-chicken-casserole/","source_name":"Julia Pacheco"},{"title":"Four-Ingredient Ravioli Bake","description":"About 15 minutes of hands-on work and 45 minutes total. Frozen cheese ravioli and jarred sauce make a simple pasta dinner.","meal_time":["lunch","dinner"],"prep_time_mins":45,"effort_score":2,"servings":4,"tags":["easy","comfort-food","oven-meal","low-active-time","family-dinner","pasta"],"image_url":"","ingredients_list":["1 bag frozen cheese ravioli pasta, 25 oz","3 cups jarred marinara sauce","1 1/2 cups shredded mozzarella cheese","1 tsp cooking oil"],"shopping_list":["1 bag frozen cheese ravioli pasta, 25 oz","3 cups jarred marinara sauce","1 1/2 cups shredded mozzarella cheese","1 tsp cooking oil"],"recipe_steps":["Heat the oven to 350°F and oil a 9-by-13-inch baking dish. Bring a pot of water to a boil.","Boil the ravioli following the bag directions, then drain. Spread a little sauce in the dish. Add the ravioli and remaining sauce, then cover with mozzarella.","Cover with foil and bake for about 20 minutes, until bubbling and 165°F in the center. Uncover for 5 minutes to melt any remaining cheese; rest 5 minutes before serving."],"cuisine":"Italian-American","user_id":null,"is_user_created":false,"source_url":"https://www.budgetbytes.com/baked-ravioli/","source_name":"Beth Moncel, Budget Bytes"},{"title":"Chicken and Potato Enchilada Skillet","description":"About 15 minutes of hands-on work and 55 minutes total. Small potato cubes simmer with canned chicken in a mild enchilada sauce.","meal_time":["lunch","dinner"],"prep_time_mins":55,"effort_score":2,"servings":2,"tags":["easy","comfort-food","one-pan","low-active-time","small-batch"],"image_url":"","ingredients_list":["1 lb russet potatoes, scrubbed and cut into small cubes","1 cup frozen diced peppers and onions","1 can cooked chicken breast, 12.5 oz, drained","1 can mild red enchilada sauce, 10 oz","1/2 cup water","1 tsp taco seasoning","1/2 cup shredded cheddar cheese"],"shopping_list":["1 lb russet potatoes, scrubbed and cut into small cubes","1 cup frozen diced peppers and onions","1 can cooked chicken breast, 12.5 oz, drained","1 can mild red enchilada sauce, 10 oz","1 tsp taco seasoning","1/2 cup shredded cheddar cheese"],"recipe_steps":["Put the potatoes, frozen vegetables, drained chicken, enchilada sauce, water and taco seasoning in a deep skillet. Stir and bring to a simmer over medium heat.","Cover and lower the heat. Simmer for 30-40 minutes, stirring occasionally, until the potatoes are fork-tender and the chicken is hot throughout. Add a splash of water if the sauce begins sticking.","Sprinkle with cheddar, cover for a minute to melt, and serve. If the potatoes are still firm, keep simmering; their size changes the cooking time."],"cuisine":"Tex-Mex","user_id":null,"is_user_created":false,"source_url":"https://www.juliapacheco.com/enchilada-potato-skillet/","source_name":"Julia Pacheco"}]'::jsonb);
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM incoming_recipes n JOIN public.recipes r
    ON regexp_replace(lower(r.title), '[^a-z0-9]', '', 'g') = regexp_replace(lower(n.title), '[^a-z0-9]', '', 'g') AND NOT r.is_user_created
    WHERE ROW(r.title,r.description,r.meal_time,r.prep_time_mins,r.effort_score,r.servings,r.tags,r.image_url,r.ingredients_list,r.shopping_list,r.recipe_steps,r.cuisine,r.user_id,r.is_user_created,r.source_url,r.source_name) IS DISTINCT FROM ROW(n.title,n.description,n.meal_time,n.prep_time_mins,n.effort_score,n.servings,n.tags,n.image_url,n.ingredients_list,n.shopping_list,n.recipe_steps,n.cuisine,n.user_id,n.is_user_created,n.source_url,n.source_name)) THEN
    RAISE EXCEPTION 'Existing title has different content; review before importing';
  END IF;
END $$;
INSERT INTO public.recipes (title, description, meal_time, prep_time_mins, effort_score, servings, tags, image_url, ingredients_list, shopping_list, recipe_steps, cuisine, user_id, is_user_created, source_url, source_name)
SELECT n.title, n.description, n.meal_time, n.prep_time_mins, n.effort_score, n.servings, n.tags, n.image_url, n.ingredients_list, n.shopping_list, n.recipe_steps, n.cuisine, n.user_id, n.is_user_created, n.source_url, n.source_name FROM incoming_recipes n
WHERE NOT EXISTS (SELECT 1 FROM public.recipes r WHERE NOT r.is_user_created
  AND regexp_replace(lower(r.title), '[^a-z0-9]', '', 'g') = regexp_replace(lower(n.title), '[^a-z0-9]', '', 'g'))
RETURNING id, title;
COMMIT;
